import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as d,X as r}from"./chunks/vendor-vueuse.XPft87tp.js";const f=JSON.parse('{"title":"Vue2 和 Vue3 的具体区别","description":"","frontmatter":{},"headers":[],"relativePath":"vue/vue2-vs-vue3.md","filePath":"vue/vue2-vs-vue3.md","lastUpdated":1785917016000}'),a={name:"vue/vue2-vs-vue3.md"};function c(i,e,n,u,s,p){return d(),o("div",null,e[0]||(e[0]=[r('<h1 id="vue2-和-vue3-的具体区别" tabindex="-1">Vue2 和 Vue3 的具体区别 <a class="header-anchor" href="#vue2-和-vue3-的具体区别" aria-label="Permalink to &quot;Vue2 和 Vue3 的具体区别&quot;">​</a></h1><h3 id="响应式系统-defineproperty-→-proxy" tabindex="-1">响应式系统：defineProperty → Proxy <a class="header-anchor" href="#响应式系统-defineproperty-→-proxy" aria-label="Permalink to &quot;响应式系统：defineProperty → Proxy&quot;">​</a></h3><p>Vue2 使用 <code>Object.defineProperty</code> 逐个劫持对象属性，因此存在三个典型限制：新增属性无法自动感知（需要 <code>$set</code>）、数组下标修改无法直接感知（需要重写 7 个数组方法）、初始化阶段需要递归遍历所有属性（深层对象初始化成本较高）。</p><p>Vue3 改用 <code>Proxy</code> 后，响应式系统可以代理整个对象，新增/删除属性能够被自动拦截，数组下标修改也可以直接支持。同时 Vue3 采用懒代理策略，只有访问到深层属性时才继续代理其子属性，初始化成本更低。</p><h3 id="api-风格-options-api-→-composition-api" tabindex="-1">API 风格：Options API → Composition API <a class="header-anchor" href="#api-风格-options-api-→-composition-api" aria-label="Permalink to &quot;API 风格：Options API → Composition API&quot;">​</a></h3><p>Vue2 的 Options API 按 data、methods、computed 等功能选项组织代码。项目规模较小时这种结构很直观，但组件变复杂后，同一业务逻辑可能分散在 data、methods、watch、computed 等多个位置，阅读和重构成本都会增加。</p><p>Vue3 的 Composition API（<code>setup</code> / <code>&lt;script setup&gt;</code>）允许开发者按<strong>逻辑关注点</strong>组织代码。以数据请求逻辑为例，data、loading、error 和 fetch 方法可以集中维护在同一个组合函数或同一段逻辑中，完整逻辑链更容易被理解和复用。</p><h3 id="生命周期变化" tabindex="-1">生命周期变化 <a class="header-anchor" href="#生命周期变化" aria-label="Permalink to &quot;生命周期变化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>Vue2</th><th>Vue3（Composition API）</th></tr></thead><tbody><tr><td>创建前</td><td><code>beforeCreate</code></td><td><code>setup()</code> 替代</td></tr><tr><td>创建后</td><td><code>created</code></td><td><code>setup()</code> 替代</td></tr><tr><td>挂载前</td><td><code>beforeMount</code></td><td><code>onBeforeMount</code></td></tr><tr><td>挂载后</td><td><code>mounted</code></td><td><code>onMounted</code></td></tr><tr><td>更新前</td><td><code>beforeUpdate</code></td><td><code>onBeforeUpdate</code></td></tr><tr><td>更新后</td><td><code>updated</code></td><td><code>onUpdated</code></td></tr><tr><td>销毁前</td><td><code>beforeDestroy</code></td><td><code>onBeforeUnmount</code></td></tr><tr><td>销毁后</td><td><code>destroyed</code></td><td><code>onUnmounted</code></td></tr></tbody></table><p>Vue3 里 <code>beforeCreate</code> 和 <code>created</code> 的作用完全被 <code>setup()</code> 取代，不再需要单独的钩子。</p><h3 id="编译与性能优化" tabindex="-1">编译与性能优化 <a class="header-anchor" href="#编译与性能优化" aria-label="Permalink to &quot;编译与性能优化&quot;">​</a></h3><p>Vue3 在编译阶段引入了静态提升（静态节点提升到 render 函数外）、Patch Flag（标记动态部分）、Block Tree（将动态节点组织为独立结构，Diff 时跳过静态子树）。这些是 Vue2 不具备的编译层优化，也是 Vue3 在大型应用中更新性能更好的重要原因。</p><h3 id="其他变化" tabindex="-1">其他变化 <a class="header-anchor" href="#其他变化" aria-label="Permalink to &quot;其他变化&quot;">​</a></h3><ul><li><strong>Fragment</strong>：Vue3 组件可以有多个根节点，不再需要额外包裹一个无语义的 <code>&lt;div&gt;</code></li><li><strong>TypeScript</strong>：Vue3 使用 TS 重写核心代码，类型推导和 IDE 提示体验更好</li><li><strong>Tree-shaking</strong>：Vue3 用 ES Module 输出，未使用的 API 打包时自动剔除</li><li><strong>Teleport</strong>：新增组件，可以把内容渲染到 DOM 树的任意位置</li></ul>',14)]))}const m=t(a,[["render",c]]);export{f as __pageData,m as default};
